<script>
 import {onMount,tick} from 'svelte';
 import WindowControls from './WindowControls.svelte';
 import {tipsWindow,tipsCapabilities} from './games-tips-state.js';
 import {tipsTopic,visibleTips,tipsSteps,tipsGuideSource,TIPS_COLLECTIONS} from './tips-content.js';
 import {tipsMenus} from './games-tips-menus.js';
 import {createGamesTipsNativeView} from './games-tips-native-view.js';
 import deskArt from './tips-desk.svg';
 import './games-tips.css';
 let {state: tipsState,profile,windowId,window:actualWindow=null,execute,registerView,available=true,active=true,controls={}}=$props();
 let root=$state(null),message=$state('');let originalState,originalProfile,originalId,facade,retired=false;
 const id=$derived(windowId??actualWindow?.id),session=$derived(tipsWindow(tipsState,id)),cap=$derived(tipsCapabilities(profile)),topics=$derived(session?visibleTips(session):[]),topic=$derived(session?.topicId?tipsTopic(session.topicId):null),source=$derived(tipsGuideSource(profile)),groups=$derived(tipsMenus({state: tipsState,profile,windowId:id})),menu=$derived(groups.find(row=>row.id===session?.menu)),topicIndex=$derived(topics.findIndex(row=>row.id===session?.topicId));
 const labels={all:'All Topics',basics:'Get Started',files:'Files & Documents',productivity:'Everyday Tasks',accessibility:'Accessibility',play:'Local Play'};
 function current(){return !retired&&root?.isConnected===true&&tipsState===originalState&&profile===originalProfile&&id===originalId;}
 async function command(suffix,payload={}){if(!current()||!available||!active)return;const response=await execute(`tips.${suffix}`,{windowId:id},payload);if(current())message=response?.status==='applied'?'':response?.error?.message??'The native guide action was not acknowledged.';return response;}
 async function menuAction(item){if(!item.enabled)return;await command(item.request.command.slice(5),item.request.payload);if(current()&&session.menu)await command('sheet',{menu:null});}
 function keyboard(event){if(!current()||!available||!active)return;if(event.key==='Escape'&&(session.sheet!=='none'||session.menu)){event.preventDefault();command('sheet',{sheet:'none',menu:null});return;}if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='f'){event.preventDefault();command('focus',{controlId:'search'});}else if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='w'){event.preventDefault();command('window.close');}else if(event.altKey&&(event.key==='ArrowLeft'||event.key==='ArrowRight')||(event.metaKey||event.ctrlKey)&&['[',']'].includes(event.key)){event.preventDefault();command('history',{direction:['ArrowLeft','['].includes(event.key)?'back':'forward'});}}
 onMount(()=>{originalState=tipsState;originalProfile=profile;originalId=id;facade=createGamesTipsNativeView({getRoot:()=>root,getState:()=>tipsState,getProfile:()=>profile,windowId:id,kind:'tips',available:()=>current()&&available,tick});registerView?.(id,facade);return()=>{retired=true;facade.destroy();registerView?.(originalId,null,facade);};});
</script>
<section bind:this={root} class="native-guide tips-native" class:classic={cap.classic} class:windows={cap.windows} class:golden={cap.golden} class:inactive={!active} class:large-text={session?.textSize==='large'} class:reduce-motion={session?.reduceMotion} data-profile={cap.era} aria-label={cap.label} role="region" tabindex="0" onkeydown={keyboard}>
 {#if session}
 <header class="guide-titlebar">{#if !cap.windows}<WindowControls {active} onclose={()=>command('window.close')} onminimize={controls.onminimize} onzoom={controls.onzoom} onfullscreen={controls.onfullscreen} fullScreen={controls.fullScreen}/>{/if}<strong>{cap.label}</strong><button data-tips-control="help" aria-label="About these offline guides" onclick={()=>command('sheet',{sheet:'help'})}>?</button></header>
 <div class="guide-layout" inert={!available||!active||session.sheet!=='none'}><aside class="guide-sidebar"><h1>{cap.label}</h1><p class="guide-kicker">Learn something useful</p><nav aria-label="Guide collections">{#each ['all',...TIPS_COLLECTIONS] as collection}<button data-tips-control={`collection:${collection}`} aria-current={session.collection===collection?'page':undefined} onclick={()=>command('collection',{collection})}>{labels[collection]}</button>{/each}</nav><div class="guide-sidebar-bottom"><strong>Offline guides</strong><small>{session.readTopics.length} of 8 topics marked read<br/>No tracking or remote content</small></div></aside>
 <main class="guide-main" data-tips-content><div class="guide-toolbar"><div class="guide-history"><button data-tips-control="back" aria-label="Back" disabled={!session.back.length} onclick={()=>command('history',{direction:'back'})}>‹</button><button data-tips-control="forward" aria-label="Forward" disabled={!session.forward.length} onclick={()=>command('history',{direction:'forward'})}>›</button></div><nav aria-label="Guide menus">{#each groups.filter(row=>row.id!=='application'&&row.id!=='window') as group}<button data-tips-control={`menu:${group.id}`} aria-expanded={session.menu===group.id} onclick={()=>command('sheet',{menu:session.menu===group.id?null:group.id})}>{group.label}</button>{/each}</nav><input type="search" data-tips-control="search" aria-label="Search offline instructions" placeholder="Search this guide" value={session.query} oninput={event=>command('search',{query:event.currentTarget.value})}/></div>
 {#if menu}<div class="guide-menu" role="menu" aria-label={menu.label}>{#each menu.children as item}<button role="menuitem" disabled={!item.enabled} data-tips-control={`item:${item.id}`} onclick={()=>menuAction(item)}>{item.checked?'✓ ':''}{item.label}<kbd>{item.shortcut??''}</kbd></button>{/each}</div>{/if}
 {#if topic}<article class="tips-article"><p class="guide-kicker">{labels[topic.collection]} · OFFLINE INSTRUCTIONS</p><h2>{topic.title}</h2><p class="guide-deck">{topic.summary}</p><img class="tips-desk-art" src={deskArt} alt="Authored illustration of a desktop with documents and a note"/><ol>{#each tipsSteps(topic,profile) as step}<li>{step}</li>{/each}</ol><div class="tips-try"><button class="guide-primary" data-tips-control={`try:${topic.id}`} onclick={()=>command('try',{topicId:topic.id})}>Try It · Open {cap.windows?({finder:'File Explorer',textedit:'Notepad',chess:'Local Chess',notes:'Sticky Notes',settings:'Settings',calculator:'Calculator'}[topic.appId]??topic.appId):({finder:'Finder',textedit:'TextEdit',chess:'Chess',notes:'Notes',settings:cap.classic?'System Preferences':'System Settings',calculator:'Calculator'}[topic.appId]??topic.appId)}</button><p>Opens the actual app through Root. No settings are silently changed and no example is marked completed.</p></div><label class="tips-read"><input type="checkbox" data-tips-control="mark-read" checked={session.readTopics.includes(topic.id)} onchange={event=>command('read',{read:event.currentTarget.checked})}/> Mark this topic read</label><div class="tips-pagination"><button data-tips-control="previous" disabled={topicIndex<=0} onclick={()=>command('step',{direction:'previous'})}>Previous Topic</button><span>{topicIndex+1} of {topics.length}</span><button data-tips-control="next" disabled={topicIndex<0||topicIndex>=topics.length-1} onclick={()=>command('step',{direction:'next'})}>Next Topic</button></div></article>
 {:else}<div class="tips-welcome"><span class="tips-bulb" aria-hidden="true">☀</span><h2>{session.query?'Search Results':labels[session.collection]}</h2><p>{session.query?`${topics.length} matching offline topic${topics.length===1?'':'s'}`:'Make yourself at home. Practical guides for the applications and settings that really work in this scene.'}</p></div><div class="guide-card-grid">{#each topics as row}<button class="guide-card tips-topic" data-tips-control={`topic:${row.id}`} onclick={()=>command('open',{topicId:row.id})}><span class="guide-kicker">{labels[row.collection]}{session.readTopics.includes(row.id)?' · READ':''}</span><h3>{row.title}</h3><p>{row.summary}</p><span class="tips-card-arrow" aria-hidden="true">›</span></button>{:else}<p class="guide-empty">No topics match. Try “keyboard”, “save”, “chess”, or clear the search.</p>{/each}</div>{/if}
 <details class="tips-source"><summary data-tips-control="source">First-party source reference</summary><p>{source.title}</p><code>{source.url}</code><p>{source.qualification}</p><p>Reference only. This guide does not fetch remote pages or open an external site by default.</p></details><p class="guide-qualification">{cap.disclosure}</p><p class="guide-status" role="status">{message}</p>
 </main></div>
 {#if session.sheet==='help'}<div class="guide-sheet" role="dialog" aria-modal="true" aria-label="About offline guides"><h2>Useful instructions, kept local</h2><p>Choose a collection, search titles and instructions, and move through topics with Previous and Next. Back and Forward preserve your collection, topic and search. Mark Read is your own reading preference, not a claim that an action succeeded.</p><p>Use View to enlarge text or reduce motion. Tab and Shift-Tab reach enabled controls; Enter or Space activates buttons. Try It opens a genuine registered app through the shared Root command endpoint.</p><p>{cap.disclosure}</p><button data-tips-control="dismiss-help" onclick={()=>command('sheet',{sheet:'none'})}>Done</button></div>{/if}
 {:else}<p role="alert">The original Tips session is unavailable.</p>{/if}
</section>
